def managed_launch(self, command, arguments, *, worktree, environment, session_file):
    if self.current:
        original, authentication = self.child.key
        candidate = original.retained_managed(command, arguments, worktree=worktree, environment=environment, session_file=session_file)
        if candidate is not None and (candidate, candidate.configuration.auth_revision()) == (original, authentication):
            return original
    return super().managed_launch(command, arguments, worktree=worktree, environment=environment, session_file=session_file)

class NativePiUnavailable(RuntimeError):
    """Tracked execution failed closed without committing a coordinator fact."""
    native_stderr = ''

    @property
    def diagnostic_evidence(self):
        return {'stderr': self.native_stderr}

    @property
    def public_failure(self):
        return f'{self}; the input is uncertain.'

    @property
    def rejected_response(self) -> pi.Response | None:
        return None

